/** Async Action */
export const AsyncAction: Story = {
  name: 'Async Action',
  tags: ['example-async-action'],
  render: () => ({ props: { example: AsyncActionExample }, template: '<ng-container *ngComponentOutlet="example" />' }),
  parameters: {
    docs: {
      source: { language: 'typescript', code: 'import { Component, signal } from \'@angular/core\';\nimport { PixelAlertDialog } from \'@pxlkit/ui-kit-angular\';\n\n@Component({\n  imports: [PixelAlertDialog],\n  template: `\n    <div>\n      <button type="button" (click)="show()">Submit</button>\n      <pxl-alert-dialog\n        [(open)]="open"\n        title="Submit report?"\n        [description]="error() ?? \'The report will be sent for review.\'"\n        actionLabel="Submit"\n        [onAction]="submit"\n        [onError]="fail"\n      />\n    </div>\n  `,\n})\nexport class AsyncAction {\n  readonly open = signal(false);\n  readonly error = signal<string | null>(null);\n  readonly submit = () => new Promise<void>((resolve) => setTimeout(resolve, 600));\n  readonly fail = (e: unknown) => this.error.set(e instanceof Error ? e.message : \'Failed\');\n\n  show(): void {\n    this.error.set(null);\n    this.open.set(true);\n  }\n}' },
    },
  },
};
